/**
 * The final-file index: which of the owner's files exist under public/assets/. It is generated by
 * `npm run tool -- assets-index` as public/assets/final-index.json and loaded once at runtime:
 *
 *   1. `globalThis.__BARDIA_FINAL_ASSETS__` (an Electron preload or a test may inject it), else
 *   2. fetch(`${BASE_URL}assets/final-index.json`), else
 *   3. XMLHttpRequest of the same URL (file:// pages in Electron, where fetch refuses the scheme).
 *
 * A missing or unreadable index means "no final files": every asset uses its placeholder. In dev
 * builds an asset whose file is not listed can also be probed directly (HEAD request), so a file
 * the owner just dropped in shows up without re-running the tool.
 */
import { notifyAssetsChanged, getAssetSettings } from './store';

/** One file entry of final-index.json. */
export interface FinalFileInfo {
  bytes: number;
  /** Content hash (cache-busting query). */
  hash: string;
  width?: number;
  height?: number;
  durationS?: number;
}

/** The parsed index. */
export interface FinalIndex {
  format: 1;
  files: Readonly<Record<string, FinalFileInfo>>;
}

export type FinalIndexStatus = 'idle' | 'loading' | 'ready' | 'failed';

const EMPTY: FinalIndex = { format: 1, files: {} };
let index: FinalIndex = EMPTY;
let status: FinalIndexStatus = 'idle';
let loading: Promise<FinalIndex> | undefined;
/** Dev probes: path → present (true) / absent (false) / pending (null). */
const probed: Record<string, boolean | null> = {};

/** Alternative extensions accepted for a manifest path (the owner may deliver another format). */
export const ALT_EXTENSIONS: Readonly<Record<string, readonly string[]>> = {
  image: ['png', 'webp', 'jpg', 'jpeg', 'avif', 'svg'],
  audio: ['ogg', 'opus', 'mp3', 'm4a', 'wav', 'flac'],
};

/** Base URL of the public assets folder (Vite BASE_URL aware; './' builds work from file://). */
export function assetsBaseUrl(): string {
  let base = '/';
  try {
    const env = (import.meta as unknown as { env?: { BASE_URL?: string } }).env;
    if (env && typeof env.BASE_URL === 'string') base = env.BASE_URL;
  } catch {
    base = '/';
  }
  if (!base.endsWith('/')) base += '/';
  return `${base}assets/`;
}

function isDev(): boolean {
  try {
    return Boolean((import.meta as unknown as { env?: { DEV?: boolean } }).env?.DEV);
  } catch {
    return false;
  }
}

/** Validates a parsed JSON value as a FinalIndex (tolerant: bad rows are dropped). */
export function parseFinalIndex(raw: unknown): FinalIndex {
  if (raw === null || typeof raw !== 'object') return EMPTY;
  const files = (raw as { files?: unknown }).files;
  if (files === null || typeof files !== 'object' || Array.isArray(files)) return EMPTY;
  const out: Record<string, FinalFileInfo> = {};
  for (const [path, info] of Object.entries(files as Record<string, unknown>)) {
    if (typeof path !== 'string' || path.includes('..') || path.startsWith('/')) continue;
    if (info === null || typeof info !== 'object') continue;
    const i = info as Record<string, unknown>;
    const bytes = typeof i.bytes === 'number' && Number.isFinite(i.bytes) ? i.bytes : 0;
    const hash = typeof i.hash === 'string' ? i.hash : '';
    const row: FinalFileInfo = { bytes, hash };
    if (typeof i.width === 'number') row.width = i.width;
    if (typeof i.height === 'number') row.height = i.height;
    if (typeof i.durationS === 'number') row.durationS = i.durationS;
    out[path] = row;
  }
  return { format: 1, files: out };
}

/** Installs an index directly (tests, Electron preload, the gallery's "simulate final" toggle). */
export function setFinalIndex(raw: FinalIndex | unknown): void {
  index = parseFinalIndex(raw);
  status = 'ready';
  notifyAssetsChanged();
}

/** The current index (empty until loaded). */
export function getFinalIndex(): FinalIndex {
  return index;
}

export function finalIndexStatus(): FinalIndexStatus {
  return status;
}

function xhrJson(url: string): Promise<unknown> {
  return new Promise((resolve, reject) => {
    try {
      const req = new XMLHttpRequest();
      req.open('GET', url, true);
      req.responseType = 'text';
      req.onload = () => {
        if ((req.status === 200 || req.status === 0) && req.responseText) {
          try {
            resolve(JSON.parse(req.responseText));
          } catch (e) {
            reject(e);
          }
        } else reject(new Error(`HTTP ${req.status}`));
      };
      req.onerror = () => reject(new Error('XHR failed'));
      req.send();
    } catch (e) {
      reject(e);
    }
  });
}

/**
 * Loads the index once (subsequent calls return the same promise). Never rejects: failures leave
 * the empty index in place and mark the status 'failed'.
 */
export function loadFinalIndex(opts: { url?: string; fetchImpl?: typeof fetch; force?: boolean } = {}): Promise<FinalIndex> {
  if (loading && !opts.force) return loading;
  const injected = (globalThis as { __BARDIA_FINAL_ASSETS__?: unknown }).__BARDIA_FINAL_ASSETS__;
  if (injected !== undefined && !opts.force) {
    setFinalIndex(injected);
    loading = Promise.resolve(index);
    return loading;
  }
  const url = opts.url ?? `${assetsBaseUrl()}final-index.json`;
  status = 'loading';
  const f = opts.fetchImpl ?? (typeof fetch === 'function' ? fetch : undefined);
  loading = (async (): Promise<FinalIndex> => {
    let raw: unknown;
    try {
      if (!f) throw new Error('no fetch');
      const res = await f(url, { cache: 'no-cache' });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const type = res.headers.get('content-type') ?? '';
      if (type.includes('text/html')) throw new Error('not found (SPA fallback)');
      raw = await res.json();
    } catch {
      try {
        raw = typeof XMLHttpRequest === 'function' ? await xhrJson(url) : undefined;
      } catch {
        raw = undefined;
      }
    }
    if (raw === undefined) {
      index = EMPTY;
      status = 'failed';
      notifyAssetsChanged();
      return index;
    }
    setFinalIndex(raw);
    return index;
  })();
  return loading;
}

/** Resets to the empty index (tests). */
export function resetFinalIndex(): void {
  index = EMPTY;
  status = 'idle';
  loading = undefined;
  for (const k of Object.keys(probed)) delete probed[k];
}

/**
 * Finds the final file for a manifest path: the exact path, else the same stem with an accepted
 * alternative extension. Returns the path that exists and its info.
 */
export function findFinalFile(path: string, kind: 'image' | 'audio'): { path: string; info: FinalFileInfo } | undefined {
  const files = index.files;
  if (Object.hasOwn(files, path)) return { path, info: files[path] as FinalFileInfo };
  const dot = path.lastIndexOf('.');
  const stem = dot > 0 ? path.slice(0, dot) : path;
  for (const ext of ALT_EXTENSIONS[kind] ?? []) {
    const alt = `${stem}.${ext}`;
    if (alt !== path && Object.hasOwn(files, alt)) return { path: alt, info: files[alt] as FinalFileInfo };
  }
  if (Object.hasOwn(probed, path) && probed[path] === true) return { path, info: { bytes: 0, hash: 'probe' } };
  return undefined;
}

/** URL of a file under public/assets/ (with a cache-busting hash when known). */
export function finalFileUrl(path: string, info?: FinalFileInfo): string {
  const enc = path.split('/').map(encodeURIComponent).join('/');
  return `${assetsBaseUrl()}${enc}${info && info.hash && info.hash !== 'probe' ? `?v=${info.hash}` : ''}`;
}

/**
 * Dev only: asks the dev server whether `path` exists (HEAD). Vite answers unknown paths with the
 * SPA's index.html, so an HTML content type counts as absent. Notifies subscribers when found.
 */
export function probeFinalFile(path: string): void {
  if (!isDev() || !getAssetSettings().devProbe || typeof fetch !== 'function') return;
  if (Object.hasOwn(probed, path)) return;
  probed[path] = null;
  fetch(finalFileUrl(path), { method: 'HEAD', cache: 'no-cache' })
    .then((res) => {
      const type = res.headers.get('content-type') ?? '';
      const found = res.ok && !type.includes('text/html');
      probed[path] = found;
      if (found) notifyAssetsChanged();
    })
    .catch(() => {
      probed[path] = false;
    });
}
